def parse(data: bytes):
    # Mirror of the reference C reader.
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    end = len(data)

    # Reader rejects files larger than 65536 bytes and files too small to
    # contain the 5-byte preamble plus the 2-byte record count.
    if end > 65536:
        return None
    if end < 5 + 2:
        return None

    if (data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24)) != 0x8B4275C0:
        return None
    if data[4] != 0x79:
        return None

    offset = 5

    def read_number(width, big_endian=False):
        nonlocal offset
        if offset > end or width > end - offset:
            return None
        value = 0
        if big_endian:
            for _ in range(width):
                value = (value << 8) | data[offset]
                offset += 1
        else:
            for i in range(width):
                value |= data[offset] << (8 * i)
                offset += 1
        return value & 0xFFFFFFFF

    record_count = read_number(2)
    if record_count is None or record_count > 8:
        return None

    h_length = read_number(2)
    if h_length is None:
        return None
    h_timestamp = read_number(1)
    if h_timestamp is None:
        return None
    h_label = read_number(4)
    if h_label is None:
        return None

    records = []
    for _ in range(record_count):
        code = read_number(2)
        if code is None:
            return None
        priority = read_number(2)
        if priority is None:
            return None
        rec_id = read_number(4)
        if rec_id is None:
            return None
        created_at = read_number(4)
        if created_at is None:
            return None
        category = read_number(2)
        if category is None:
            return None
        # Same key order as the reader's JSON output.
        records.append({
            "category": category,
            "code": code,
            "created_at": created_at,
            "id": rec_id,
            "priority": priority,
        })

    if offset != end:
        return None

    return {
        "header": {
            "label": h_label,
            "length": h_length,
            "timestamp": h_timestamp,
        },
        "records": records,
    }
