MAGIC = 0xE38F52D3
MAX_FILE_SIZE = 65536
MAX_RECORDS = 8


def _read_uint(data, offset, end, width):
    """Little-endian unsigned integer read matching reader.c's read_number."""
    if offset > end or width > end - offset:
        return None, offset
    value = 0
    for i in range(width):
        value |= data[offset + i] << (8 * i)
    return value, offset + width


def parse(data: bytes):
    try:
        data = bytes(data)
    except Exception:
        return None

    end = len(data)
    if end < 5 + 4 or end > MAX_FILE_SIZE:
        return None

    if (data[0] | (data[1] << 8) | (data[2] << 16) | (data[3] << 24)) != MAGIC:
        return None
    if data[4] != 0x91:
        return None

    offset = 5
    record_count, offset = _read_uint(data, offset, end, 4)
    if record_count is None or record_count > MAX_RECORDS:
        return None

    label, offset = _read_uint(data, offset, end, 2)
    if label is None:
        return None
    stock, offset = _read_uint(data, offset, end, 2)
    if stock is None:
        return None

    records = []
    for _ in range(record_count):
        source, offset = _read_uint(data, offset, end, 4)
        if source is None:
            return None
        enabled, offset = _read_uint(data, offset, end, 2)
        if enabled is None:
            return None
        region, offset = _read_uint(data, offset, end, 1)
        if region is None:
            return None
        records.append({"enabled": enabled, "region": region, "source": source})

    if offset != end:
        return None

    return {"header": {"label": label, "stock": stock}, "records": records}
