        amount = read_uint(2)
        if amount is None:
            return None
        created_at = read_uint(4)
        if created_at is None:
            return None
        enabled = read_uint(4)
        if enabled is None:
            return None

        records.append({
            "amount": amount,
            "code": code,
            "created_at": created_at,
            "enabled": enabled,
            "timestamp": timestamp,
        })

    # No trailing bytes are tolerated.
    if offset != end:
        return None

    return {
        "header": {"label": label},
        "records": records,
    }
